import { cacheLife, cacheTag } from 'next/cache'
import { getAllProducts } from './db'

export async function getCachedProducts() {
  'use cache'
  cacheTag('products')
  cacheLife('max')

  return getAllProducts()
}

import { revalidateTag } from 'next/cache'
import { after } from 'next/server'
import { getCachedProducts } from '@/lib/products'
import { syncCatalogFromErp } from '@/lib/db'

export default async function Page() {
  const products = await getCachedProducts()

  async function syncCatalog() {
    'use server'

    // Kick off the ERP/PIM sync without blocking the admin; it runs after
    // the response is sent so the page stays responsive.
    after(async () => {
      await syncCatalogFromErp()
    })

    // Stale-while-revalidate: mark the "products" tag stale and refresh it
    // in the background. Every cached view using this tag serves the current
    // snapshot now and becomes up to date shortly after.
    revalidateTag('products', 'max')
  }

  return (
    <div>
      <h1>Product Catalog</h1>

      <form action={syncCatalog}>
        <button type="submit">Sync latest catalog</button>
      </form>

      <table>
        <thead>
          <tr>
            <th>ID</th>
            <th>Name</th>
            <th>Price</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr key={product.id}>
              <td>{product.id}</td>
              <td>{product.name}</td>
              <td>${product.price}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

